import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { roomAPI, bookingAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';
import LocationPicker from '../components/LocationPicker';

const OwnerDashboard = () => {
  const { user } = useAuth();
  const [rooms, setRooms] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [roomBookings, setRoomBookings] = useState({}); // NOUVEAU: réservations groupées par salle
  const [expandedRooms, setExpandedRooms] = useState([]); // NOUVEAU: salles dépliées
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState({
    rooms: true,
    bookings: true,
    stats: true
  });
  
  const [newRoom, setNewRoom] = useState({
    title: '',
    description: '',
    capacity: '',
    price_per_hour: '',
    address: '',
    city: '',
    postal_code: '',
    country: 'France'
  });
  const [imageFile, setImageFile] = useState(null);
  const [showRoomForm, setShowRoomForm] = useState(false);

  useEffect(() => {
    if (user) {
      fetchOwnerData();
    }
  }, [user]);

  const fetchOwnerData = async () => {
    await Promise.all([
      fetchOwnerRooms(),
      fetchOwnerBookings(),
      fetchOwnerStats()
    ]);
  };

  const fetchOwnerRooms = async () => {
    try {
      const response = await roomAPI.getOwnerRooms();
      setRooms(response.data.rooms || []);
    } catch (error) {
      console.error('Erreur chargement salles:', error);
    } finally {
      setLoading(prev => ({ ...prev, rooms: false }));
    }
  };

  const fetchOwnerBookings = async () => {
    try {
      const response = await bookingAPI.getOwnerBookings();
      const bookingsData = response.data.bookings || [];
      setBookings(bookingsData);
      
      // Grouper les réservations par salle
      const grouped = {};
      bookingsData.forEach(booking => {
        if (!grouped[booking.room_id]) {
          grouped[booking.room_id] = [];
        }
        grouped[booking.room_id].push(booking);
      });
      setRoomBookings(grouped);
      
    } catch (error) {
      console.error('Erreur chargement réservations:', error);
    } finally {
      setLoading(prev => ({ ...prev, bookings: false }));
    }
  };

  const fetchOwnerStats = async () => {
    try {
      const response = await roomAPI.getOwnerStats();
      setStats(response.data.stats);
    } catch (error) {
      console.error('Erreur chargement stats:', error);
    } finally {
      setLoading(prev => ({ ...prev, stats: false }));
    }
  };

  // NOUVEAU: Basculer l'affichage des réservations d'une salle
  const toggleRoomBookings = (roomId) => {
    if (expandedRooms.includes(roomId)) {
      setExpandedRooms(expandedRooms.filter(id => id !== roomId));
    } else {
      setExpandedRooms([...expandedRooms, roomId]);
    }
  };

  // NOUVEAU: Obtenir les réservations d'une salle spécifique
  const getRoomBookings = (roomId) => {
    return roomBookings[roomId] || [];
  };

  // NOUVEAU: Compter les réservations par statut pour une salle
  const getBookingStats = (roomId) => {
    const roomBookingsList = getRoomBookings(roomId);
    return {
      total: roomBookingsList.length,
      pending: roomBookingsList.filter(b => b.status === 'pending').length,
      confirmed: roomBookingsList.filter(b => b.status === 'confirmed').length,
      completed: roomBookingsList.filter(b => b.status === 'completed').length,
      cancelled: roomBookingsList.filter(b => b.status === 'cancelled').length
    };
  };

  const handleNewRoomChange = (e) => {
    setNewRoom({
      ...newRoom,
      [e.target.name]: e.target.value
    });
  };

  const handleImageChange = (e) => {
    if (e.target.files && e.target.files[0]) {
      setImageFile(e.target.files[0]);
    }
  };

  const handleAddRoom = async (e) => {
    e.preventDefault();
    
    const formData = new FormData();
    
    Object.keys(newRoom).forEach(key => {
      formData.append(key, newRoom[key]);
    });
    
    if (imageFile) {
      formData.append('image', imageFile);
    }
    
    try {
      const response = await fetch('http://localhost:5000/api/rooms', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: formData
      });
      
      const data = await response.json();
      
      if (data.success) {
        setRooms([...rooms, data.data.room]);
        setNewRoom({
          title: '',
          description: '',
          capacity: '',
          price_per_hour: '',
          address: '',
          city: '',
          postal_code: '',
          country: 'France'
        });
        setImageFile(null);
        setShowRoomForm(false);
        fetchOwnerStats();
      } else {
        console.error('Erreur création salle:', data.message);
        alert(data.message || 'Erreur lors de la création de la salle');
      }
    } catch (error) {
      console.error('Erreur création salle:', error);
      alert('Erreur lors de la création de la salle');
    }
  };

  const handleConfirmBooking = async (bookingId) => {
    try {
      const response = await bookingAPI.confirm(bookingId);
      if (response.success) {
        fetchOwnerBookings(); // Recharger les réservations
      }
    } catch (error) {
      console.error('Erreur confirmation:', error);
    }
  };

  const handleCancelBooking = async (bookingId) => {
    if (!window.confirm('Annuler cette réservation ?')) return;
    
    try {
      // Note: On utilise cancel au lieu de delete
      const response = await bookingAPI.cancel(bookingId);
      if (response.success) {
        fetchOwnerBookings(); // Recharger les réservations
      }
    } catch (error) {
      console.error('Erreur annulation:', error);
    }
  };

  const handleDeleteRoom = async (roomId) => {
    if (!window.confirm('Supprimer cette salle ?')) return;
    
    try {
      const response = await roomAPI.delete(roomId);
      if (response.success) {
        setRooms(rooms.filter(r => r.id !== roomId));
        fetchOwnerStats();
      }
    } catch (error) {
      console.error('Erreur suppression:', error);
    }
  };

  return (
    <div className="main-content">
      <div className="card">
        <h1>Espace Propriétaire</h1>
        <p>Bienvenue dans votre espace de gestion, <strong>{user?.first_name}</strong></p>
      </div>

      {/* Statistiques */}
      <div className="card">
        <h2> Statistiques</h2>
        {loading.stats ? (
          <p>Chargement des statistiques...</p>
        ) : stats ? (
          <div className="stats-grid" style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
            gap: '20px',
            marginTop: '20px'
          }}>
            <div className="stat-card" style={{
              background: 'linear-gradient(135deg, #53cca68d 0%)',
              color: 'white',
              padding: '25px',
              borderRadius: '12px',
              textAlign: 'center',
              boxShadow: '0 4px 15px rgba(254, 252, 252, 0.1)'
            }}>
              <h3 style={{ fontSize: '2.5rem', margin: '0 0 10px 0' }}>{stats.total_rooms || 0}</h3>
              <p style={{ margin: 0, fontSize: '1.1rem' }}>Salles totales</p>
            </div>
            <div className="stat-card" style={{
              background: 'linear-gradient(135deg, #53cca68d 0%)',
              color: 'white',
              padding: '25px',
              borderRadius: '12px',
              textAlign: 'center',
              boxShadow: '0 4px 15px rgba(0,0,0,0.1)'
            }}>
              <h3 style={{ fontSize: '2.5rem', margin: '0 0 10px 0' }}>{stats.available_rooms || 0}</h3>
              <p style={{ margin: 0, fontSize: '1.1rem' }}>Salles disponibles</p>
            </div>
            <div className="stat-card" style={{
              background: 'linear-gradient(135deg, #53cca68d 0%)',
              color: 'white',
              padding: '25px',
              borderRadius: '12px',
              textAlign: 'center',
              boxShadow: '0 4px 15px rgba(0,0,0,0.1)'
            }}>
              <h3 style={{ fontSize: '2.5rem', margin: '0 0 10px 0' }}>{bookings.length}</h3>
              <p style={{ margin: 0, fontSize: '1.1rem' }}>Réservations</p>
            </div>
            
          </div>
        ) : (
          <p>Aucune statistique disponible</p>
        )}
      </div>







      {/* Gestion des salles AVEC RÉSERVATIONS - STYLE AMÉLIORÉ */}
      <div className="card" style={{
        marginTop: '2rem',
        padding: '2rem',
        borderRadius: '15px',
        boxShadow: '0 5px 20px rgba(0, 0, 0, 0.1)',
        background: 'white'
      }}>
        <div className="section-header" style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          marginBottom: '2rem',
          paddingBottom: '1rem',
          borderBottom: '2px solid #f0f2f5'
        }}>
          <div>
            <h2 style={{ 
              margin: 0, 
              color: '#2d3748',
              fontSize: '1.8rem',
              display: 'flex',
              alignItems: 'center',
              gap: '10px'
            }}>
              <span style={{
                background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                color: 'white',
                width: '40px',
                height: '40px',
                borderRadius: '50%',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontSize: '1.2rem'
              }}>🏢</span>
              Mes salles ({rooms.length})
            </h2>
            <p style={{ margin: '5px 0 0 0', color: '#718096', fontSize: '1.2rem' }}>
              Gérez vos salles et leurs réservations
            </p>
          </div>
          <button 
            onClick={() => setShowRoomForm(!showRoomForm)}
            className="btn btn-primary"
            style={{
              background: 'linear-gradient(135deg, #246773 0%, #764ba2 100%)',
              border: 'none',
              padding: '12px 24px',
              borderRadius: '8px',
              fontSize: '1rem',
              fontWeight: '600',
              display: 'flex',
              alignItems: 'center',
              gap: '8px',
              transition: 'all 0.3s ease',
              boxShadow: '0 4px 15px rgba(102, 126, 234, 0.3)'
            }}
            onMouseOver={(e) => {
              e.target.style.transform = 'translateY(-2px)';
              e.target.style.boxShadow = '0 6px 20px rgba(102, 126, 234, 0.4)';
            }}
            onMouseOut={(e) => {
              e.target.style.transform = 'translateY(0)';
              e.target.style.boxShadow = '0 4px 15px rgba(102, 126, 234, 0.3)';
            }}
          >
            <span style={{ fontSize: '1.2rem' }}>{showRoomForm ? '×' : '+'}</span>
            {showRoomForm ? 'Annuler' : 'Ajouter une salle'}
          </button>
        </div>

        {showRoomForm && (
          <form onSubmit={handleAddRoom} className="room-form" encType="multipart/form-data" style={{
            background: '#f8f9fa',
            padding: '2rem',
            borderRadius: '12px',
            marginBottom: '2rem',
            border: '1px solid #105ba7'
          }}>
            
            <h3>Nouvelle salle</h3>
            
            <div className="form-group">
              <label>Image de la salle (optionnel)</label>
              <input
                type="file"
                name="image"
                accept="image/*"
                onChange={handleImageChange}
                className="form-input"
              />
              {imageFile && (
                <p style={{ marginTop: '5px', color: 'green' }}>
                  ✅ Image sélectionnée: {imageFile.name}
                </p>
              )}
              <small style={{ color: '#666' }}>
                Formats acceptés: JPG, PNG, GIF, WebP (max 5MB)
              </small>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label>Titre *</label>
                <input
                  type="text"
                  name="title"
                  value={newRoom.title}
                  onChange={handleNewRoomChange}
                  required
                  className="form-input"
                />
              </div>
              <div className="form-group">
                <label>Ville *</label>
                <input
                  type="text"
                  name="city"
                  value={newRoom.city}
                  onChange={handleNewRoomChange}
                  required
                  className="form-input"
                />
              </div>
            </div>

            {newRoom.city && (
              <div className="form-group">
                <LocationPicker
                  city={newRoom.city}
                  onLocationSelected={(lat, lng) => {
                    setNewRoom({
                      ...newRoom,
                      latitude: lat,
                      longitude: lng
                    });
                  }}
                />
              </div>
            )}

            <div className="form-row">
              <div className="form-group">
                <label>Capacité *</label>
                <input
                  type="number"
                  name="capacity"
                  value={newRoom.capacity}
                  onChange={handleNewRoomChange}
                  required
                  className="form-input"
                  min="1"
                />
              </div>
              <div className="form-group">
                <label>Prix/heure (DA) *</label>
                <input
                  type="number"
                  name="price_per_hour"
                  value={newRoom.price_per_hour}
                  onChange={handleNewRoomChange}
                  required
                  className="form-input"
                  min="0"
                  step="0.01"
                />
              </div>
            </div>

            <div className="form-group">
              <label>Adresse *</label>
              <input
                type="text"
                name="address"
                value={newRoom.address}
                onChange={handleNewRoomChange}
                required
                className="form-input"
              />
            </div>

            <div className="form-group">
              <label>Description</label>
              <textarea
                name="description"
                value={newRoom.description}
                onChange={handleNewRoomChange}
                className="form-input"
                rows="3"
              />
            </div>
            
            <input
              type="hidden"
              name="latitude"
              value={newRoom.latitude || ''}
            />
            <input
              type="hidden"
              name="longitude"
              value={newRoom.longitude || ''}
            />

            <button type="submit" className="btn btn-primary">
              Créer la salle
            </button>
          </form>
        )}

        {loading.rooms ? (
          <div style={{ 
            textAlign: 'center', 
            padding: '3rem',
            color: '#6395c7'
          }}>
            <div style={{
              width: '50px',
              height: '50px',
              border: '3px solid #f3f3f3',
              borderTop: '3px solid #667eea',
              borderRadius: '50%',
              animation: 'spin 1s linear infinite',
              margin: '0 auto 1rem'
            }}></div>
            <p>Chargement de vos salles...</p>
          </div>
        ) : rooms.length > 0 ? (
          <div className="rooms-list" style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
            {rooms.map(room => {
              const roomBookingStats = getBookingStats(room.id);
              const isExpanded = expandedRooms.includes(room.id);
              
              return (
                <div key={room.id} className="room-item" style={{
                  background: 'white',
                  borderRadius: '12px',
                  padding: '1.5rem',
                  border: '1px solid #e9ecef',
                  transition: 'all 0.3s ease',
                  boxShadow: '0 2px 10px rgba(0,0,0,0.05)',
                  marginBottom: '1rem'
                }}
                onMouseOver={(e) => {
                  e.currentTarget.style.boxShadow = '0 8px 25px rgba(0,0,0,0.1)';
                  e.currentTarget.style.transform = 'translateY(-3px)';
                }}
                onMouseOut={(e) => {
                  e.currentTarget.style.boxShadow = '0 2px 10px rgba(0,0,0,0.05)';
                  e.currentTarget.style.transform = 'translateY(0)';
                }}>
                  {/* EN-TÊTE DE LA SALLE */}
                  <div className="room-header" style={{ 
                    display: 'flex', 
                    justifyContent: 'space-between', 
                    alignItems: 'flex-start',
                    marginBottom: '1rem'
                  }}>
                    <div className="room-info" style={{ flex: 1 }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '15px', marginBottom: '10px' }}>
                        <div style={{
                          width: '50px',
                          height: '50px',
                          background: 'linear-gradient(135deg, #5f8db550 0%)',
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          color: 'white',
                          fontSize: '1.5rem',
                          fontWeight: 'bold'
                        }}>
                          {room.title.charAt(0)}
                        </div>
                        <div>
                          <h4 style={{ 
                            margin: 0, 
                            color: '#2d3748',
                            fontSize: '1.4rem',
                            fontWeight: '600'
                          }}>
                            {room.title}
                          </h4>
                          <div style={{ 
                            display: 'flex', 
                            gap: '15px', 
                            marginTop: '5px',
                            color: '#4b515a',
                            fontSize: '1rem'
                          }}>
                            <span style={{ display: 'flex', alignItems: 'center', gap: '5px' }}>
                              📍 {room.city}
                            </span>
                            <span style={{ display: 'flex', alignItems: 'center', gap: '5px' }}>
                              👥 {room.capacity} pers.
                            </span>
                            <span style={{ display: 'flex', alignItems: 'center', gap: '5px' }}>
                              prix:{room.price_per_hour}DA/h
                            </span>
                          </div>
                        </div>
                      </div>
                      
                      {/* STATUT ET STATISTIQUES */}
                      <div style={{ 
                        display: 'flex', 
                        alignItems: 'center', 
                        gap: '15px',
                        marginTop: '10px',
                        flexWrap: 'wrap'
                      }}>
                        <span style={{
                          padding: '5px 12px',
                          borderRadius: '20px',
                          fontSize: '0.85rem',
                          fontWeight: '500',
                          background: room.is_available ? 
                            'linear-gradient(135deg, #9bebae4d 0%)' : 
                            'linear-gradient(135deg, #f8d7da 0%, #f5c6cb 100%)',
                          color: room.is_available ? '#1c1e1c' : '#721c24',
                          display: 'flex',
                          alignItems: 'center',
                          gap: '5px'
                        }}>
                          {room.is_available ? '✅ Disponible' : '❌ Indisponible'}
                        </span>
                        
                        {/* STATISTIQUES DES RÉSERVATIONS */}
                        {roomBookingStats.total > 0 && (
                          <div className="booking-stats" style={{ 
                            display: 'flex',
                            gap: '10px',
                            flexWrap: 'wrap'
                          }}>
                            <span style={{
                              padding: '5px 12px',
                              borderRadius: '20px',
                              fontSize: '0.85rem',
                              fontWeight: '500',
                              background: 'linear-gradient(135deg, #e3f2fd 0%, #bbdefb 100%)',
                              color: '#1565c0',
                              display: 'flex',
                              alignItems: 'center',
                              gap: '5px'
                            }}>
                              📅 {roomBookingStats.total} réservation(s)
                            </span>
                            
                            {roomBookingStats.pending > 0 && (
                              <span style={{
                                padding: '5px 12px',
                                borderRadius: '20px',
                                fontSize: '0.85rem',
                                fontWeight: '500',
                                background: 'linear-gradient(135deg, #fff3cd 0%, #ffeaa7 100%)',
                                color: '#ff0505',
                                display: 'flex',
                                alignItems: 'center',
                                gap: '5px'
                              }}>
                                ⏳ {roomBookingStats.pending} en attente
                              </span>
                            )}
                            
                            {roomBookingStats.confirmed > 0 && (
                              <span style={{
                                padding: '5px 12px',
                                borderRadius: '20px',
                                fontSize: '0.85rem',
                                fontWeight: '500',
                                background: 'linear-gradient(135deg, #d4edda 0%, #c3e6cb 100%)',
                                color: '#155724',
                                display: 'flex',
                                alignItems: 'center',
                                gap: '5px'
                              }}>
                                ✅ {roomBookingStats.confirmed} confirmée(s)
                              </span>
                            )}
                          </div>
                        )}
                      </div>
                    </div>
                    
                    {/* ACTIONS */}
                    <div className="room-actions" style={{ 
                      display: 'flex', 
                      gap: '10px',
                      flexDirection: 'column',
                      alignItems: 'flex-end'
                    }}>
                      <div style={{ display: 'flex', gap: '8px' }}>
                        <Link to={`/rooms/${room.id}`} className="btn btn-secondary btn-sm" style={{
                          padding: '8px 16px',
                          background: 'linear-gradient(135deg, #6c757d 0%, #5a6268 100%)',
                          border: 'none',
                          borderRadius: '6px',
                          color: 'white',
                          textDecoration: 'none',
                          fontSize: '0.9rem',
                          fontWeight: '500',
                          transition: 'all 0.3s ease',
                          display: 'flex',
                          alignItems: 'center',
                          gap: '5px'
                        }}
                        onMouseOver={(e) => {
                          e.target.style.transform = 'translateY(-2px)';
                          e.target.style.boxShadow = '0 4px 12px rgba(108, 117, 125, 0.3)';
                        }}
                        onMouseOut={(e) => {
                          e.target.style.transform = 'translateY(0)';
                          e.target.style.boxShadow = 'none';
                        }}>
                           Voir
                        </Link>
                        
                        <button 
                          onClick={() => handleDeleteRoom(room.id)}
                          className="btn btn-danger btn-sm"
                          style={{
                            padding: '8px 16px',
                            background: 'linear-gradient(135deg, #dc3545 0%, #c82333 100%)',
                            border: 'none',
                            borderRadius: '6px',
                            color: 'white',
                            fontSize: '0.9rem',
                            fontWeight: '500',
                            transition: 'all 0.3s ease',
                            display: 'flex',
                            alignItems: 'center',
                            gap: '5px'
                          }}
                          onMouseOver={(e) => {
                            e.target.style.transform = 'translateY(-2px)';
                            e.target.style.boxShadow = '0 4px 12px rgba(220, 53, 69, 0.3)';
                          }}
                          onMouseOut={(e) => {
                            e.target.style.transform = 'translateY(0)';
                            e.target.style.boxShadow = 'none';
                          }}
                        >
                           Supprimer
                        </button>
                      </div>
                      
                      {/* BOUTON VOIR RÉSERVATIONS */}
                      {roomBookingStats.total > 0 && (
                        <button 
                          onClick={() => toggleRoomBookings(room.id)}
                          className="btn btn-primary btn-sm"
                          style={{
                            padding: '10px 20px',
                            background: isExpanded ? 
                              'linear-gradient(135deg, #667eea 0%, #764ba2 100%)' : 
                              'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                            border: 'none',
                            borderRadius: '8px',
                            color: 'white',
                            fontSize: '0.95rem',
                            fontWeight: '600',
                            transition: 'all 0.3s ease',
                            display: 'flex',
                            alignItems: 'center',
                            gap: '8px',
                            width: '100%',
                            justifyContent: 'center',
                            marginTop: '10px'
                          }}
                          onMouseOver={(e) => {
                            e.target.style.transform = 'translateY(-2px)';
                            e.target.style.boxShadow = '0 6px 20px rgba(102, 126, 234, 0.3)';
                          }}
                          onMouseOut={(e) => {
                            e.target.style.transform = 'translateY(0)';
                            e.target.style.boxShadow = 'none';
                          }}
                        >
                          <span style={{ fontSize: '1.1rem' }}>
                            {isExpanded ? '▲' : '▼'}
                          </span>
                          {isExpanded ? 'Masquer les réservations' : 'Voir les réservations'}
                          <span style={{
                            background: 'rgba(255, 255, 255, 0.2)',
                            padding: '2px 8px',
                            borderRadius: '12px',
                            fontSize: '0.8rem'
                          }}>
                            {roomBookingStats.total}
                          </span>
                        </button>
                      )}
                    </div>
                  </div>

                  {/* RÉSERVATIONS DE LA SALLE */}
                  {isExpanded && roomBookingStats.total > 0 && (
                    <div className="room-bookings" style={{ 
                      marginTop: '1.5rem',
                      padding: '1.5rem',
                      background: 'linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%)',
                      borderRadius: '10px',
                      border: '1px solid #dee2e6'
                    }}>
                      <h5 style={{ 
                        margin: '0 0 1rem 0', 
                        color: '#2d3748',
                        fontSize: '1.2rem',
                        fontWeight: '600',
                        display: 'flex',
                        alignItems: 'center',
                        gap: '10px'
                      }}>
                        <span style={{
                          background: 'linear-gradient(135deg, #fdfdfd 0%)',
                          color: 'white',
                          width: '30px',
                          height: '30px',
                          borderRadius: '50%',
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          fontSize: '0.9rem'
                        }}>📅</span>
                        Réservations pour cette salle
                      </h5>
                      
                      <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                        {getRoomBookings(room.id).map(booking => (
                          <div key={booking.id} className="booking-item" style={{
                            padding: '1rem',
                            background: 'white',
                            borderRadius: '8px',
                            borderLeft: `4px solid ${
                              booking.status === 'confirmed' ? '#28a745' :
                              booking.status === 'pending' ? '#ffc107' :
                              booking.status === 'cancelled' ? '#dc3545' : '#6c757d'
                            }`,
                            boxShadow: '0 2px 8px rgba(0,0,0,0.04)',
                            transition: 'all 0.2s ease'
                          }}
                          onMouseOver={(e) => {
                            e.currentTarget.style.boxShadow = '0 4px 12px rgba(0,0,0,0.08)';
                            e.currentTarget.style.transform = 'translateX(5px)';
                          }}
                          onMouseOut={(e) => {
                            e.currentTarget.style.boxShadow = '0 2px 8px rgba(0,0,0,0.04)';
                            e.currentTarget.style.transform = 'translateX(0)';
                          }}>
                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                              <div style={{ flex: 1 }}>
                                <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '8px' }}>
                                  <strong style={{ color: '#2d3748', fontSize: '1.1rem' }}>
                                    Réservation #{booking.id}
                                  </strong>
                                  <span className={`status-badge ${booking.status}`} style={{
                                    padding: '4px 12px',
                                    borderRadius: '20px',
                                    fontSize: '0.8rem',
                                    fontWeight: '600',
                                    background: 
                                      booking.status === 'confirmed' ? 'linear-gradient(135deg, #d4edda 0%, #c3e6cb 100%)' :
                                      booking.status === 'pending' ? 'linear-gradient(135deg, #fff3cd 0%, #ffeaa7 100%)' :
                                      booking.status === 'cancelled' ? 'linear-gradient(135deg, #f8d7da 0%, #f5c6cb 100%)' : '#e2e3e5',
                                    color: 
                                      booking.status === 'confirmed' ? '#155724' :
                                      booking.status === 'pending' ? '#856404' :
                                      booking.status === 'cancelled' ? '#721c24' : '#383d41'
                                  }}>
                                    {booking.status === 'confirmed' ? '✅ Confirmée' :
                                     booking.status === 'pending' ? '⏳ En attente' :
                                     booking.status === 'cancelled' ? '❌ Annulée' : booking.status}
                                  </span>
                                </div>
                                
                                <div style={{ 
                                  display: 'grid',
                                  gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
                                  gap: '15px',
                                  marginTop: '10px'
                                }}>
                                  <div>
                                    <p style={{ margin: '4px 0', fontSize: '0.95rem', color: '#4a5568' }}>
                                      <strong>👤 Client:</strong> {booking.client_first_name} {booking.client_last_name}
                                    </p>
                                    <p style={{ margin: '4px 0', fontSize: '0.95rem', color: '#4a5568' }}>
                                      <strong>💰 Prix:</strong> {booking.total_price}DA
                                    </p>
                                  </div>
                                  <div>
                                    <p style={{ margin: '4px 0', fontSize: '0.95rem', color: '#4a5568' }}>
                                      <strong>📅 Début:</strong> {new Date(booking.start_datetime).toLocaleString('fr-FR')}
                                    </p>
                                    <p style={{ margin: '4px 0', fontSize: '0.95rem', color: '#4a5568' }}>
                                      <strong>📅 Fin:</strong> {new Date(booking.end_datetime).toLocaleString('fr-FR')}
                                    </p>
                                  </div>
                                </div>
                              </div>
                              
                              {/* ACTIONS SUR LA RÉSERVATION */}
                              {booking.status === 'pending' && (
                                <div className="booking-actions" style={{ 
                                  display: 'flex', 
                                  gap: '10px',
                                  marginLeft: '20px'
                                }}>
                                  <button 
                                    onClick={() => handleConfirmBooking(booking.id)}
                                    className="btn btn-success btn-sm"
                                    style={{
                                      padding: '8px 16px',
                                      background: 'linear-gradient(135deg, #28a746c1 0%)',
                                      border: 'none',
                                      borderRadius: '6px',
                                      color: 'white',
                                      fontSize: '0.85rem',
                                      fontWeight: '600',
                                      transition: 'all 0.3s ease',
                                      display: 'flex',
                                      alignItems: 'center',
                                      gap: '5px'
                                    }}
                                    onMouseOver={(e) => {
                                      e.target.style.transform = 'translateY(-2px)';
                                      e.target.style.boxShadow = '0 4px 12px rgba(40, 167, 69, 0.3)';
                                    }}
                                    onMouseOut={(e) => {
                                      e.target.style.transform = 'translateY(0)';
                                      e.target.style.boxShadow = 'none';
                                    }}
                                  >
                                     Confirmer
                                  </button>
                                  <button 
                                    onClick={() => handleCancelBooking(booking.id)}
                                    className="btn btn-danger btn-sm"
                                    style={{
                                      padding: '8px 16px',
                                      background: 'linear-gradient(135deg, #dc3546d3 0%)',
                                      border: 'none',
                                      borderRadius: '6px',
                                      color: 'white',
                                      fontSize: '0.85rem',
                                      fontWeight: '600',
                                      transition: 'all 0.3s ease',
                                      display: 'flex',
                                      alignItems: 'center',
                                      gap: '5px'
                                    }}
                                    onMouseOver={(e) => {
                                      e.target.style.transform = 'translateY(-2px)';
                                      e.target.style.boxShadow = '0 4px 12px rgba(220, 53, 69, 0.3)';
                                    }}
                                    onMouseOut={(e) => {
                                      e.target.style.transform = 'translateY(0)';
                                      e.target.style.boxShadow = 'none';
                                    }}
                                  >
                                     Refuser
                                  </button>
                                </div>
                              )}
                            </div>
                          </div>
                        ))}
                      </div>
                      
                      {getRoomBookings(room.id).length === 0 && (
                        <div style={{ 
                          textAlign: 'center', 
                          padding: '2rem',
                          color: '#718096',
                          fontStyle: 'italic'
                        }}>
                          Aucune réservation pour cette salle
                        </div>
                      )}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        ) : (
          <div style={{ 
            textAlign: 'center', 
            padding: '3rem',
            color: '#718096'
          }}>
            <div style={{
              fontSize: '4rem',
              marginBottom: '1rem',
              opacity: '0.3'
            }}></div>
            <h3 style={{ color: '#4a5568', marginBottom: '0.5rem' }}>
              Aucune salle créée
            </h3>
            <p style={{ marginBottom: '1.5rem' }}>
              Commencez par ajouter votre première salle pour la proposer à la location.
            </p>
           
          </div>
        )}
      </div>


    </div>
  );



const styleSheet = document.createElement("style");
styleSheet.textContent = styles;
document.head.appendChild(styleSheet);
};

export default OwnerDashboard;
